def isbn_valid(s: str) -> bool:
    cleaned = s.replace("-", "").replace(" ", "")

    if len(cleaned) == 10:
        # First 9 characters must be digits
        if not cleaned[:9].isdigit():
            return False

        # Last character must be a digit or 'X'
        if cleaned[9].isdigit():
            last_val = int(cleaned[9])
        elif cleaned[9] == 'X':
            last_val = 10
        else:
            return False

        total = sum((i + 1) * int(cleaned[i]) for i in range(9)) + 10 * last_val
        return total % 11 == 0

    elif len(cleaned) == 13:
        # All 13 characters must be digits
        if not cleaned.isdigit():
            return False

        total = sum(int(digit) * (1 if i % 2 == 0 else 3) for i, digit in enumerate(cleaned))
        return total % 10 == 0

    return False
